// Minimal C smoke test for the flat moss-transcribe C-API. Compiled as C (not
// C++) and linked against libmoss-transcribe.so to prove the extern-"C" ABI and
// the dlopen-friendly shared library work end to end.
//
//   cc tests/capi_smoke.c -Iinclude -Lbuild-shared -lmoss-transcribe -o /tmp/capi_smoke
//   LD_LIBRARY_PATH=build-shared /tmp/capi_smoke [model.gguf] [audio.wav]

#include "moss_transcribe_capi.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char** argv) {
    const char* model = (argc > 1) ? argv[1] : "models/moss-transcribe-f32.gguf";
    const char* wav   = (argc > 2) ? argv[2] : "tests/fixtures/short.wav";

    printf("abi_version = %d\n", moss_transcribe_capi_abi_version());

    moss_transcribe_ctx* ctx = moss_transcribe_capi_load(model);
    if (!ctx) {
        fprintf(stderr, "FAIL: load(%s) returned NULL\n", model);
        return 1;
    }

    char* text = moss_transcribe_capi_transcribe_path(ctx, wav, 300);
    if (!text) {
        fprintf(stderr, "FAIL: transcribe_path: %s\n",
                moss_transcribe_capi_last_error(ctx));
        moss_transcribe_capi_free(ctx);
        return 1;
    }

    printf("transcript: %s\n", text);

    int ok = 1;
    if (!strstr(text, "my fellow Americans")) {
        fprintf(stderr, "FAIL: transcript missing \"my fellow Americans\"\n");
        ok = 0;
    }
    if (!strstr(text, "[S01]")) {
        fprintf(stderr, "FAIL: transcript missing \"[S01]\"\n");
        ok = 0;
    }

    moss_transcribe_capi_free_string(text);
    moss_transcribe_capi_free(ctx);

    if (ok) { printf("OK: smoke test passed\n"); return 0; }
    return 1;
}

#ifndef MOSS_TRANSCRIBE_CAPI_H
#define MOSS_TRANSCRIBE_CAPI_H

#ifdef __cplusplus
extern "C" {
#endif

// Flat C-API for moss-transcribe.cpp -- designed for dlopen / cgo / purego
// (LocalAI). All functions are extern "C" and never let a C++ exception cross
// the boundary. The model is loaded ONCE into an opaque `moss_transcribe_ctx`
// and reused across transcribe calls. Returned strings are malloc'd UTF-8 owned
// by the caller and must be released with moss_transcribe_capi_free_string.

// ABI version of this header/implementation. Bump on any breaking change to the
// function signatures or semantics below.
int moss_transcribe_capi_abi_version(void);

// Opaque transcription context (wraps a loaded model + last-error buffer).
typedef struct moss_transcribe_ctx moss_transcribe_ctx;

// Load a GGUF model. Returns an owning context, or NULL on failure.
// The returned context must be released with moss_transcribe_capi_free.
moss_transcribe_ctx* moss_transcribe_capi_load(const char* gguf_path);

// Free a context obtained from moss_transcribe_capi_load. Safe on NULL.
void moss_transcribe_capi_free(moss_transcribe_ctx* ctx);

// Transcribe a WAV file (any sample rate/channel layout; decoded, downmixed to
// mono and resampled to 16 kHz internally). `max_new` caps the number of newly
// generated tokens; `max_new <= 0` uses the GGUF's default_max_new_tokens.
// On success returns a malloc'd, NUL-terminated UTF-8 transcript of the form
// "[start][Sxx]text[end]..." (free with moss_transcribe_capi_free_string). On
// error returns NULL and sets the context's last error (see
// moss_transcribe_capi_last_error).
char* moss_transcribe_capi_transcribe_path(moss_transcribe_ctx* ctx,
                                           const char* wav_path, int max_new);

// Transcribe in-memory mono float PCM (`samples`, length `n_samples`). If
// `sample_rate != 16000` the audio is linearly resampled to 16 kHz first.
// `max_new` is as in moss_transcribe_capi_transcribe_path. On success returns a
// malloc'd UTF-8 transcript (free with moss_transcribe_capi_free_string); on
// error returns NULL and sets the context's last error.
char* moss_transcribe_capi_transcribe_pcm(moss_transcribe_ctx* ctx,
                                          const float* samples, int n_samples,
                                          int sample_rate, int max_new);

// Free a string previously returned by moss_transcribe_capi_transcribe_*.
// Safe on NULL.
void moss_transcribe_capi_free_string(char* s);

// Human-readable description of the last error on `ctx`, or "" if none.
// The returned pointer is owned by the context and valid until the next call on
// it (or until moss_transcribe_capi_free). Returns "" if `ctx` is NULL.
const char* moss_transcribe_capi_last_error(moss_transcribe_ctx* ctx);

#ifdef __cplusplus
} // extern "C"
#endif

#endif // MOSS_TRANSCRIBE_CAPI_H

#include "model_loader.hpp"
#include "backend.hpp"
#include "common.hpp"

#include <cstdio>
#include <cstring>
#include <vector>

namespace mt {

ModelLoader::ModelLoader() = default;

ModelLoader::~ModelLoader() {
    if (promote_buffer_) ggml_backend_buffer_free(promote_buffer_);
    if (promote_ctx_)    ggml_free(promote_ctx_);
    if (backend_buffer_) ggml_backend_buffer_free(backend_buffer_);
    if (gguf_)           gguf_free(gguf_);
    if (ctx_)            ggml_free(ctx_);
}

bool ModelLoader::load(const std::string& path) {
    if (gguf_ || ctx_) {
        MT_LOGE("ModelLoader::load called twice");
        return false;
    }

    // Load gguf metadata only (no_alloc=true). The actual tensor data is
    // copied into a backend buffer below so it lives wherever ggml's
    // active backend wants — CPU RAM by default, GPU VRAM when CUDA /
    // Metal / Vulkan / hipBLAS is selected.
    struct gguf_init_params p {};
    p.no_alloc = true;
    p.ctx      = &ctx_;

    gguf_ = gguf_init_from_file(path.c_str(), p);
    if (!gguf_) {
        MT_LOGE("ModelLoader: gguf_init_from_file failed for %s", path.c_str());
        return false;
    }

    const int64_t n = gguf_get_n_tensors(gguf_);
    tensor_names_.reserve(static_cast<size_t>(n));
    for (int64_t i = 0; i < n; ++i) {
        const char* name = gguf_get_tensor_name(gguf_, i);
        if (!name) continue;
        struct ggml_tensor* t = ggml_get_tensor(ctx_, name);
        if (!t) {
            MT_LOGW("ModelLoader: tensor %s present in gguf header but missing from ctx", name);
            continue;
        }
        tensor_names_.emplace_back(name);
        tensor_by_name_.emplace(name, t);
    }

    // Allocate every tensor in ctx_ on the active backend's buffer. After
    // this each ggml_tensor's `data` pointer references backend memory
    // (host pages on CPU; device VRAM on GPU). Reads/writes have to go
    // through ggml_backend_tensor_{set,get}. Tensor-less ggufs (e.g. the
    // tokenizer-only file) skip allocation entirely.
    if (n > 0) {
        backend_buffer_ = ggml_backend_alloc_ctx_tensors(ctx_, mt::backend());
        if (!backend_buffer_) {
            MT_LOGE("ModelLoader: backend_alloc_ctx_tensors failed");
            return false;
        }
    }

    // Parse the mtd.* metadata block (independent of tensor data).
    read_config();

    if (n == 0) {
        MT_LOGI("loaded %s: %lld tensors, %lld kv (no tensor data)",
                    path.c_str(), 0LL, static_cast<long long>(gguf_get_n_kv(gguf_)));
        return true;
    }

    // Stream the on-disk tensor bytes into the backend buffer. We open
    // the file ourselves (gguf has the byte offsets but doesn't expose a
    // streaming reader) and read each tensor in turn into a small CPU
    // staging buffer, then upload via ggml_backend_tensor_set. The
    // staging buffer is sized to the largest tensor we encounter.
    FILE* fp = std::fopen(path.c_str(), "rb");
    if (!fp) {
        MT_LOGE("ModelLoader: fopen %s failed", path.c_str());
        return false;
    }
    const size_t data_off = gguf_get_data_offset(gguf_);
    std::vector<uint8_t> stage;
    for (int64_t i = 0; i < n; ++i) {
        const char* name = gguf_get_tensor_name(gguf_, i);
        if (!name) continue;
        struct ggml_tensor* t = ggml_get_tensor(ctx_, name);
        if (!t) continue;
        const size_t off = data_off + gguf_get_tensor_offset(gguf_, i);
        const size_t sz  = gguf_get_tensor_size(gguf_, i);
        if (sz == 0) continue;
        if (stage.size() < sz) stage.resize(sz);
        if (std::fseek(fp, static_cast<long>(off), SEEK_SET) != 0
         || std::fread(stage.data(), 1, sz, fp) != sz) {
            MT_LOGE("ModelLoader: read failed for tensor %s", name);
            std::fclose(fp);
            return false;
        }
        ggml_backend_tensor_set(t, stage.data(), 0, sz);
    }
    std::fclose(fp);

    MT_LOGI("loaded %s: %lld tensors, %lld kv (backend=%s)",
                path.c_str(),
                static_cast<long long>(n),
                static_cast<long long>(gguf_get_n_kv(gguf_)),
                mt::backend_name());
    return true;
}

void ModelLoader::read_config() {
    // Text (Qwen3).
    cfg_.text_vocab    = (int) get_u32("mtd.text.vocab_size", 151936);
    cfg_.text_hidden   = (int) get_u32("mtd.text.hidden", 1024);
    cfg_.text_ffn      = (int) get_u32("mtd.text.ffn", 3072);
    cfg_.text_layers   = (int) get_u32("mtd.text.n_layers", 28);
    cfg_.text_heads    = (int) get_u32("mtd.text.n_heads", 16);
    cfg_.text_kv_heads = (int) get_u32("mtd.text.n_kv_heads", 8);
    cfg_.text_head_dim = (int) get_u32("mtd.text.head_dim", 128);
    cfg_.text_rms_eps  = get_f32("mtd.text.rms_eps", 1e-6f);
    cfg_.text_rope_theta = get_f32("mtd.text.rope_theta", 1e6f);
    cfg_.text_max_pos  = (int) get_u32("mtd.text.max_pos", 40960);
    cfg_.text_tied     = get_bool("mtd.text.tied", true);

    // Audio (Whisper).
    cfg_.audio_mel_bins    = (int) get_u32("mtd.audio.mel_bins", 80);
    cfg_.audio_d_model     = (int) get_u32("mtd.audio.d_model", 1024);
    cfg_.audio_layers      = (int) get_u32("mtd.audio.n_layers", 24);
    cfg_.audio_heads       = (int) get_u32("mtd.audio.n_heads", 16);
    cfg_.audio_ffn         = (int) get_u32("mtd.audio.ffn", 4096);
    cfg_.audio_max_src_pos = (int) get_u32("mtd.audio.max_src_pos", 1500);
    cfg_.audio_act         = get_str("mtd.audio.act", "gelu");
    cfg_.audio_scale_embed = get_bool("mtd.audio.scale_embed", false);

    // Bridge.
    cfg_.audio_token_id   = (int) get_u32("mtd.audio_token_id", 151671);
    cfg_.audio_merge_size = (int) get_u32("mtd.audio_merge_size", 4);
    cfg_.adaptor_input_dim = (int) get_u32("mtd.adaptor_input_dim", 4096);
    cfg_.adaptor_norm_eps  = get_f32("mtd.adaptor_norm_eps", 1e-6f);

    // Mel front-end.
    cfg_.feat_sr            = (int) get_u32("mtd.feat.sr", 16000);
    cfg_.feat_n_fft         = (int) get_u32("mtd.feat.n_fft", 400);
    cfg_.feat_hop           = (int) get_u32("mtd.feat.hop", 160);
    cfg_.feat_size          = (int) get_u32("mtd.feat.feature_size", 80);
    cfg_.feat_n_samples     = (int) get_u32("mtd.feat.n_samples", 480000);
    cfg_.feat_nb_max_frames = (int) get_u32("mtd.feat.nb_max_frames", 3000);
    cfg_.feat_dither        = get_f32("mtd.feat.dither", 0.0f);

    // Audio-span.
    cfg_.audio_tokens_per_second   = get_f32("mtd.audio_tokens_per_second", 12.5f);
    cfg_.time_marker_every_seconds = (int) get_u32("mtd.time_marker_every_seconds", 5);
    cfg_.enable_time_marker        = get_bool("mtd.enable_time_marker", true);

    // Generation.
    cfg_.eos_token_id          = (int) get_u32("mtd.eos_token_id", 151645);
    cfg_.pad_token_id          = (int) get_u32("mtd.pad_token_id", 151643);
    cfg_.default_max_new_tokens = (int) get_u32("mtd.default_max_new_tokens", 5120);
    cfg_.default_prompt        = get_str("mtd.default_prompt", "");
    cfg_.digit_token_ids       = get_i32_array("mtd.digit_token_ids");

    // Architecture.
    cfg_.arch = get_str("general.architecture", "");
}

struct ggml_tensor* ModelLoader::tensor(const std::string& name) const {
    auto it = tensor_by_name_.find(name);
    return (it == tensor_by_name_.end()) ? nullptr : it->second;
}

void ModelLoader::promote_small_f16_to_f32(size_t max_elems) {
    if (!ctx_) return;
    // Identify f16 tensors small enough to be worth promoting (norm
    // scales, biases, gammas, tiny embeddings — anything ggml's CPU
    // element-wise ops won't auto-cast).
    size_t to_promote = 0;
    for (const auto& kv : tensor_by_name_) {
        const struct ggml_tensor* t = kv.second;
        if (!t || t->type != GGML_TYPE_F16) continue;
        if ((size_t)ggml_nelements(t) > max_elems) continue;
        ++to_promote;
    }
    if (to_promote == 0) return;

    // Sibling ctx for the promoted tensor metadata. no_alloc=true — the
    // data lives in a backend buffer we allocate after building the ctx,
    // mirroring the main load() path so promoted tensors are usable on
    // any backend (CPU, CUDA, etc.).
    const size_t mem_size = (to_promote + 1) * ggml_tensor_overhead() + 64ull * 1024;
    struct ggml_init_params ip {};
    ip.mem_size = mem_size;
    ip.no_alloc = true;
    promote_ctx_ = ggml_init(ip);
    if (!promote_ctx_) {
        MT_LOGE("promote: ggml_init(%zu) failed", mem_size);
        return;
    }

    // Build the new f32 tensors first, then allocate the backend buffer
    // for them in one shot. This matches the gguf load pattern.
    struct PromotionEntry { struct ggml_tensor* nt; std::string key; };
    std::vector<PromotionEntry> pending;
    pending.reserve(to_promote);
    size_t f32_bytes = 0;
    for (const auto& kv : tensor_by_name_) {
        struct ggml_tensor* t = kv.second;
        if (!t || t->type != GGML_TYPE_F16) continue;
        const size_t n = ggml_nelements(t);
        if (n > max_elems) continue;
        struct ggml_tensor* nt = ggml_new_tensor(promote_ctx_, GGML_TYPE_F32,
                                                  ggml_n_dims(t), t->ne);
        if (!nt) continue;
        ggml_set_name(nt, kv.first.c_str());
        pending.push_back({nt, kv.first});
        f32_bytes += n * sizeof(float);
    }
    promote_buffer_ = ggml_backend_alloc_ctx_tensors(promote_ctx_, mt::backend());
    if (!promote_buffer_) {
        MT_LOGE("promote: backend_alloc_ctx_tensors failed");
        return;
    }

    // Convert each f16 source to f32 via a CPU staging buffer (read from
    // backend, convert in CPU code, write back to the destination
    // backend buffer). Same path works whether backend is CPU or GPU.
    std::vector<ggml_fp16_t> stage_in;
    std::vector<float>       stage_out;
    for (auto& e : pending) {
        struct ggml_tensor* src_t = tensor_by_name_[e.key];
        const size_t n = ggml_nelements(src_t);
        if (stage_in.size() < n)  stage_in.resize(n);
        if (stage_out.size() < n) stage_out.resize(n);
        ggml_backend_tensor_get(src_t, stage_in.data(), 0, n * sizeof(ggml_fp16_t));
        for (size_t i = 0; i < n; ++i) stage_out[i] = ggml_fp16_to_fp32(stage_in[i]);
        ggml_backend_tensor_set(e.nt, stage_out.data(), 0, n * sizeof(float));
        // Repoint the lookup map so callers see the f32 promoted tensor.
        tensor_by_name_[e.key] = e.nt;
    }
    MT_LOGI("promoted %zu small f16 tensors to f32 (threshold %zu elems, %.1f MB)",
                pending.size(), max_elems, f32_bytes / (1024.0 * 1024.0));
}

bool ModelLoader::has(const std::string& name) const {
    return tensor_by_name_.count(name) > 0;
}

namespace {
int64_t find_key(struct gguf_context* g, const std::string& key) {
    return gguf_find_key(g, key.c_str());  // returns -1 if missing
}
}  // namespace

int32_t ModelLoader::get_i32(const std::string& key, int32_t def) const {
    if (!gguf_) return def;
    int64_t k = find_key(gguf_, key);
    if (k < 0) return def;
    enum gguf_type t = gguf_get_kv_type(gguf_, k);
    if (t == GGUF_TYPE_INT32)  return gguf_get_val_i32(gguf_, k);
    if (t == GGUF_TYPE_UINT32) return static_cast<int32_t>(gguf_get_val_u32(gguf_, k));
    return def;
}

int64_t ModelLoader::get_i64(const std::string& key, int64_t def) const {
    if (!gguf_) return def;
    int64_t k = find_key(gguf_, key);
    if (k < 0) return def;
    enum gguf_type t = gguf_get_kv_type(gguf_, k);
    if (t == GGUF_TYPE_INT64)  return gguf_get_val_i64(gguf_, k);
    if (t == GGUF_TYPE_UINT64) return static_cast<int64_t>(gguf_get_val_u64(gguf_, k));
    if (t == GGUF_TYPE_INT32)  return gguf_get_val_i32(gguf_, k);
    if (t == GGUF_TYPE_UINT32) return gguf_get_val_u32(gguf_, k);
    return def;
}

uint32_t ModelLoader::get_u32(const std::string& key, uint32_t def) const {
    return static_cast<uint32_t>(get_i32(key, static_cast<int32_t>(def)));
}

float ModelLoader::get_f32(const std::string& key, float def) const {
    if (!gguf_) return def;
    int64_t k = find_key(gguf_, key);
    if (k < 0) return def;
    enum gguf_type t = gguf_get_kv_type(gguf_, k);
    if (t == GGUF_TYPE_FLOAT32) return gguf_get_val_f32(gguf_, k);
    if (t == GGUF_TYPE_FLOAT64) return static_cast<float>(gguf_get_val_f64(gguf_, k));
    return def;
}

bool ModelLoader::get_bool(const std::string& key, bool def) const {
    if (!gguf_) return def;
    int64_t k = find_key(gguf_, key);
    if (k < 0) return def;
    if (gguf_get_kv_type(gguf_, k) == GGUF_TYPE_BOOL) return gguf_get_val_bool(gguf_, k);
    return def;
}

std::string ModelLoader::get_str(const std::string& key, const std::string& def) const {
    if (!gguf_) return def;
    int64_t k = find_key(gguf_, key);
    if (k < 0) return def;
    if (gguf_get_kv_type(gguf_, k) != GGUF_TYPE_STRING) return def;
    const char* s = gguf_get_val_str(gguf_, k);
    return s ? std::string(s) : def;
}

std::vector<int32_t> ModelLoader::get_i32_array(const std::string& key) const {
    std::vector<int32_t> out;
    if (!gguf_) return out;
    int64_t k = find_key(gguf_, key);
    if (k < 0) return out;
    if (gguf_get_kv_type(gguf_, k) != GGUF_TYPE_ARRAY) return out;
    enum gguf_type at = gguf_get_arr_type(gguf_, k);
    if (at != GGUF_TYPE_INT32 && at != GGUF_TYPE_UINT32) return out;
    const size_t n = gguf_get_arr_n(gguf_, k);
    out.resize(n);
    const auto* data = static_cast<const int32_t*>(gguf_get_arr_data(gguf_, k));
    if (data && n) std::memcpy(out.data(), data, n * sizeof(int32_t));
    return out;
}

std::vector<float> ModelLoader::get_f32_array(const std::string& key) const {
    std::vector<float> out;
    if (!gguf_) return out;
    int64_t k = find_key(gguf_, key);
    if (k < 0) return out;
    if (gguf_get_kv_type(gguf_, k) != GGUF_TYPE_ARRAY) return out;
    if (gguf_get_arr_type(gguf_, k) != GGUF_TYPE_FLOAT32) return out;
    const size_t n = gguf_get_arr_n(gguf_, k);
    out.resize(n);
    const auto* data = static_cast<const float*>(gguf_get_arr_data(gguf_, k));
    if (data && n) std::memcpy(out.data(), data, n * sizeof(float));
    return out;
}

std::vector<std::string> ModelLoader::get_str_array(const std::string& key) const {
    std::vector<std::string> out;
    if (!gguf_) return out;
    int64_t k = find_key(gguf_, key);
    if (k < 0) return out;
    if (gguf_get_kv_type(gguf_, k) != GGUF_TYPE_ARRAY) return out;
    if (gguf_get_arr_type(gguf_, k) != GGUF_TYPE_STRING) return out;
    const size_t n = gguf_get_arr_n(gguf_, k);
    out.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        const char* s = gguf_get_arr_str(gguf_, k, i);
        out.emplace_back(s ? s : "");
    }
    return out;
}

}  // namespace mt

#include "moss_transcribe_capi.h"

#include "model_loader.hpp"
#include "transcribe.hpp"
#include "audio_io.hpp"

#include <cstdlib>
#include <cstring>
#include <exception>
#include <memory>
#include <new>
#include <string>
#include <vector>

// ABI version. Bump on any breaking change to the C-API surface.
#define MOSS_TRANSCRIBE_CAPI_ABI_VERSION 1

// The opaque context: a loaded (and f16->f32 promoted) model plus a buffer for
// the last error message. The model is loaded once and reused across calls.
struct moss_transcribe_ctx {
    std::unique_ptr<mt::ModelLoader> loader;
    std::string last_error;
};

namespace {

// malloc a NUL-terminated copy of `s` so a C consumer frees it with free()
// (matching moss_transcribe_capi_free_string). Returns NULL on OOM.
char* dup_to_c(const std::string& s) {
    char* buf = static_cast<char*>(std::malloc(s.size() + 1));
    if (!buf) return nullptr;
    std::memcpy(buf, s.data(), s.size());
    buf[s.size()] = '\0';
    return buf;
}

// Resolve the effective max_new-tokens budget: `max_new <= 0` means use the
// GGUF's default_max_new_tokens (falling back to 5120 if the model set none),
// matching the CLI.
int resolve_max_new(const mt::ModelLoader& m, int max_new) {
    if (max_new > 0) return max_new;
    const int def = m.config().default_max_new_tokens;
    return def > 0 ? def : 5120;
}

} // namespace

extern "C" int moss_transcribe_capi_abi_version(void) {
    return MOSS_TRANSCRIBE_CAPI_ABI_VERSION;
}

extern "C" moss_transcribe_ctx* moss_transcribe_capi_load(const char* gguf_path) {
    if (!gguf_path) return nullptr;
    try {
        auto loader = std::make_unique<mt::ModelLoader>();
        if (!loader->load(gguf_path)) return nullptr;  // bad/missing GGUF
        // ggml's CPU element-wise ops don't auto-cast f32 + f16, so promote the
        // small f16 tensors up front (same as the CLI transcribe path).
        loader->promote_small_f16_to_f32();
        auto* ctx = new (std::nothrow) moss_transcribe_ctx();
        if (!ctx) return nullptr;
        ctx->loader = std::move(loader);
        return ctx;
    } catch (...) {
        // Never let an exception cross the boundary.
        return nullptr;
    }
}

extern "C" void moss_transcribe_capi_free(moss_transcribe_ctx* ctx) {
    delete ctx;  // safe on nullptr; ~unique_ptr releases the model.
}

extern "C" char* moss_transcribe_capi_transcribe_path(moss_transcribe_ctx* ctx,
                                                      const char* wav_path,
                                                      int max_new) {
    if (!ctx) return nullptr;
    if (!ctx->loader) { ctx->last_error = "context has no loaded model"; return nullptr; }
    if (!wav_path)    { ctx->last_error = "wav_path is NULL"; return nullptr; }
    try {
        const int budget = resolve_max_new(*ctx->loader, max_new);
        std::string text = mt::transcribe_wav(*ctx->loader, wav_path, budget);
        if (text.empty()) { ctx->last_error = "transcription failed"; return nullptr; }
        ctx->last_error.clear();
        char* out = dup_to_c(text);
        if (!out) { ctx->last_error = "out of memory"; return nullptr; }
        return out;
    } catch (const std::exception& e) {
        ctx->last_error = e.what();
        return nullptr;
    } catch (...) {
        ctx->last_error = "unknown error";
        return nullptr;
    }
}

extern "C" char* moss_transcribe_capi_transcribe_pcm(moss_transcribe_ctx* ctx,
                                                     const float* samples,
                                                     int n_samples, int sample_rate,
                                                     int max_new) {
    if (!ctx) return nullptr;
    if (!ctx->loader) { ctx->last_error = "context has no loaded model"; return nullptr; }
    if (!samples || n_samples < 0) { ctx->last_error = "invalid samples buffer"; return nullptr; }
    if (sample_rate <= 0) { ctx->last_error = "invalid sample rate"; return nullptr; }
    try {
        std::vector<float> pcm(samples, samples + n_samples);
        // Resample to 16 kHz mono if needed (input is assumed mono).
        if (sample_rate != 16000) {
            pcm = mt::resample_linear(pcm, sample_rate, 16000);
        }
        const int budget = resolve_max_new(*ctx->loader, max_new);
        std::string text = mt::transcribe_pcm16k(*ctx->loader, pcm, budget);
        if (text.empty()) { ctx->last_error = "transcription failed"; return nullptr; }
        ctx->last_error.clear();
        char* out = dup_to_c(text);
        if (!out) { ctx->last_error = "out of memory"; return nullptr; }
        return out;
    } catch (const std::exception& e) {
        ctx->last_error = e.what();
        return nullptr;
    } catch (...) {
        ctx->last_error = "unknown error";
        return nullptr;
    }
}

extern "C" void moss_transcribe_capi_free_string(char* s) {
    std::free(s);
}

extern "C" const char* moss_transcribe_capi_last_error(moss_transcribe_ctx* ctx) {
    if (!ctx) return "";
    return ctx->last_error.c_str();
}

#ifndef MT_MODEL_LOADER_HPP
#define MT_MODEL_LOADER_HPP

// Lightweight gguf reader. Wraps ggml's gguf_* API with a name→tensor map
// and typed metadata accessors. Also parses the `mtd.*` metadata KV block
// into a mt::Config on load().

#include "config.hpp"

#include "ggml-alloc.h"
#include "ggml-backend.h"
#include "ggml.h"
#include "gguf.h"

#include <cstdint>
#include <memory>
#include <string>
#include <unordered_map>
#include <vector>

namespace mt {

class ModelLoader {
public:
    ModelLoader();
    ~ModelLoader();

    ModelLoader(const ModelLoader&)            = delete;
    ModelLoader& operator=(const ModelLoader&) = delete;

    // Open the gguf file and load all tensor metadata + weight bytes into a
    // newly-created ggml_context. Tensors are looked up by name with `tensor`.
    // Also fills config() from the `mtd.*` KV block.
    bool load(const std::string& path);

    // Parsed model configuration (populated by load()).
    const Config& config() const { return cfg_; }

    // Tensor lookup. Returns nullptr if not found.
    struct ggml_tensor* tensor(const std::string& name) const;
    bool                has(const std::string& name) const;

    // Cast all small (1-D / scalar / few-row) f16 tensors to f32 in-place.
    // ggml's CPU element-wise ops don't auto-cast f32 + f16, so norm scales,
    // biases, gammas and tiny embeddings need to be promoted up front when
    // the gguf was written in fp16. Large matmul weights stay fp16.
    //
    // `max_elems` is the size threshold (in scalar element count) for promotion.
    void promote_small_f16_to_f32(size_t max_elems = 65536);

    const std::vector<std::string>& tensor_names() const { return tensor_names_; }

    // Metadata accessors. Return the provided default if the key is absent or
    // wrong-typed.
    int32_t     get_i32(const std::string& key, int32_t       def = 0)  const;
    int64_t     get_i64(const std::string& key, int64_t       def = 0)  const;
    uint32_t    get_u32(const std::string& key, uint32_t      def = 0)  const;
    float       get_f32(const std::string& key, float         def = 0)  const;
    bool        get_bool(const std::string& key, bool         def = false) const;
    std::string get_str(const std::string& key, const std::string& def = {}) const;
    std::vector<int32_t> get_i32_array(const std::string& key) const;
    std::vector<float>   get_f32_array(const std::string& key) const;
    std::vector<std::string> get_str_array(const std::string& key) const;

    // Raw access if a caller needs more.
    struct gguf_context* gguf_ctx() const { return gguf_; }
    struct ggml_context* ggml_ctx() const { return ctx_; }

private:
    // Fill cfg_ from the gguf `mtd.*` (and general.*) KV block.
    void read_config();

    struct gguf_context*      gguf_           = nullptr;
    struct ggml_context*      ctx_            = nullptr;  // tensor metadata
    struct ggml_context*      promote_ctx_    = nullptr;  // f32 promoted tensors
    ggml_backend_buffer_t     backend_buffer_ = nullptr;  // owns the actual weight data
    ggml_backend_buffer_t     promote_buffer_ = nullptr;  // owns promoted weight data
    std::vector<std::string>  tensor_names_;
    std::unordered_map<std::string, struct ggml_tensor*> tensor_by_name_;
    Config                    cfg_{};
};

}  // namespace mt

#endif  // MT_MODEL_LOADER_HPP

# moss-transcribe.cpp — Phase 2: Tokenizer, Decode & E2E Transcription (M4–M5) Implementation Plan

> **For agentic workers:** REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development to implement this plan task-by-task. Steps use checkbox (`- [ ]`) syntax.

**Goal:** Complete the model to a **working end-to-end transcription from a fixture that matches the upstream PyTorch output**: Qwen2 BPE tokenizer → audio-span builder with time markers (bit-exact `input_ids`) → Qwen3-0.6B decoder (parity vs reference logits) → masked_scatter fusion → greedy generate → `transcribe` CLI whose text equals `baseline.text`.

**Architecture:** Builds on Phase 1's proven audio front end (wav→`audio_embeds`, all cos=1.0). Vendors the Qwen3 decoder graph + Qwen2 byte-BPE tokenizer from `moss-tts.cpp`, adapted to read `mt::Config` and the `qwen3.blk.{i}.*.weight` / `token_embd.weight` / `qwen3.output_norm.weight` tensors already in the GGUF. Decode is autoregressive greedy over the fused audio+text embedding stream; the transcript (with `[start][Sxx]text[end]`) is emitted as plain text tokens.

**Tech Stack:** C++17, ggml (submodule, already pinned). No new Python needed (baselines already dumped in Phase 1).

## Global Constraints

- Namespace `mt::`; GGUF KV prefix `mtd.`; C-API prefix `moss_transcribe_capi_`; test env `MTD_TEST_GGUF`, `MTD_TEST_BASELINE`. Parity F32/CPU.
- Text/Qwen3 constants (read from GGUF via `mt::Config`, never hardcode): hidden 1024, ffn 3072, 28 layers, 16 Q heads, 8 KV heads, **head_dim 128** (independent of hidden/n_heads), rms_eps 1e-6, **rope_theta 1e6**, vocab 151936, tied lm_head. RoPE = **NEOX (half-split)**. q_norm/k_norm = per-head RMSNorm over head_dim applied **BEFORE RoPE** using rms_eps. GQA via `ggml_mul_mat` broadcast (n_heads multiple of n_kv_heads). `ggml_mul_mat_set_prec(scores, GGML_PREC_F32)`. Qwen3 attention has **no biases**. SwiGLU MLP.
- Decoder tensor names (already in GGUF): `qwen3.blk.{i}.{attn_norm,attn_q,attn_k,attn_v,attn_o,attn_q_norm,attn_k_norm,ffn_norm,ffn_gate,ffn_up,ffn_down}.weight`, `qwen3.output_norm.weight`, `token_embd.weight`. **lm_head is tied** → logits = `token_embd.weight @ hidden`. There is NO separate `lm_head` tensor (the checkpoint ships none — the reference requires `tie_weights()`).
- Tokenizer keys in GGUF: `tokenizer.tokens`, `tokenizer.token_type`, `tokenizer.merges`, `tokenizer.special_tokens_ids`, `tokenizer.special_tokens_text`, `tokenizer.bos_id`(-1), `tokenizer.eos_id`(151645), `tokenizer.pad_id`(151643). audio ids: `audio_pad`=151671; `audio_start`/`audio_end` are special tokens. `mtd.digit_token_ids` = 10 ids for "0".."9".
- Audio-span (read from `mt::Config`): `audio_tokens_per_second`=12.5, **`time_marker_every_seconds`=5** (the SHIPPED value — NOT 2), `enable_time_marker`=true, `audio_token_id`=151671, `audio_merge_size`=4.
- Prompt (fixed): `<|im_start|>system\nYou are a helpful assistant.<|im_end|>\n<|im_start|>user\n<|audio_start|><|audio_pad|><|audio_end|>\n{prompt}<|im_end|>\n<|im_start|>assistant\n`, `{prompt}` = `mtd.default_prompt`. The single `<|audio_pad|>` is expanded by the audio-span builder.
- Generation: greedy (argmax), EOS = 151645, default max_new_tokens 5120 (test uses fewer). Output post-processing = `text.strip()`.
- Trimming/chunking (from Phase 1): audio split into 30s (480000-sample) chunks; per-chunk `token_len=(unpadded_chunk_samples-1)//1280+1` (stride=hop160·2·merge4=1280); each chunk's encoder output trimmed to `token_len·4` frames, all chunks concatenated, then merged+adaptor'd.
- Gold baselines (Phase 1, on disk): `tests/fixtures/baseline_short.gguf` (jfk 11s, 1 chunk, 138 audio tokens, input_ids len 227, generated_ids len 298; `baseline.text` = correct JFK transcript) and `baseline_long.gguf` (>30s, 2 chunks, 550 audio tokens). Tensors: `input_ids`, `fused_embeds` [1024,227], `lm_hidden` [1024,227], `prompt_logits` [151936,227], `generated_ids`, `audio_embeds` [1024,138].
- DRY, YAGNI, TDD, frequent commits. Do NOT loosen parity tolerances to force a pass.

