    if (!mttest::load_baseline(base, "fused_embeds", fused, sh)) return 1;  // [seq, hidden]
    const int seq = (int)sh[0], H = (int)sh[1];

    mt::Qwen3Decoder dec;
    if (!dec.load(m, seq + 512)) return 1;

    std::vector<float> hid;
    if (!dec.prefill(fused, seq, &hid)) return 1;                           // [seq, hidden]

    std::vector<float> ref_h; std::vector<int64_t> hsh;
    if (!mttest::load_baseline(base, "lm_hidden", ref_h, hsh)) return 1;
    bool ok = mttest::compare(hid, ref_h, "lm_hidden", 5e-2f, 5e-2f);

    // argmax of last-position logits must match the reference greedy first token.
    std::vector<float> last(hid.end() - H, hid.end());
    auto logits = dec.logits_from_hidden(last);
    if (logits.empty()) { std::fprintf(stderr, "logits_from_hidden failed\n"); return 1; }
    int am = 0;
    for (int i = 1; i < (int)logits.size(); ++i) if (logits[i] > logits[am]) am = i;

    std::vector<float> ref_logits; std::vector<int64_t> lsh;
    if (!mttest::load_baseline(base, "prompt_logits", ref_logits, lsh)) return 1;  // [seq, vocab]
    const int V = (int)lsh[1];
    int ram = 0; const float* rl = &ref_logits[(size_t)(seq - 1) * V];
    for (int i = 1; i < V; ++i) if (rl[i] > rl[ram]) ram = i;

    if (am != ram) { std::fprintf(stderr, "argmax %d vs ref %d\n", am, ram); ok = false; }
    std::printf("qwen3 lm_hidden + last-pos argmax (%d==%d)\n", am, ram);
    return ok ? 0 : 1;
}

#include "tokenizer.hpp"
#include "parity.hpp"
#include <cstdlib>
#include <cstdio>
int main() {
    const char* gguf = std::getenv("MTD_TEST_GGUF");
    const char* base = std::getenv("MTD_TEST_BASELINE");
    if (!gguf || !base) return 77;
    mt::ModelLoader m; if (!m.load(gguf)) return 1;
    mt::Tokenizer tok; if (!tok.load(m)) { std::fprintf(stderr,"tok load failed\n"); return 1; }
    // 1) special ids
    if (tok.eos_id() != 151645) { std::fprintf(stderr,"eos %d\n", tok.eos_id()); return 1; }
    if (tok.token_to_id("<|audio_pad|>") != 151671) return 1;
    // 2) round-trip on ASCII + CJK
    for (const char* s : {"Hello, world.", "ask what you can do", "请将音频转写为文本"}) {
        auto ids = tok.encode(s);
        if (tok.decode(ids) != s) { std::fprintf(stderr,"roundtrip fail: %s -> %s\n", s, tok.decode(ids).c_str()); return 1; }
    }
    // 3) decode the reference generated tokens (after the prompt) == baseline.text
    std::vector<int32_t> gen; if (!mttest::load_baseline_i32(base, "generated_ids", gen)) return 1;
    std::vector<int32_t> ids_prompt; if (!mttest::load_baseline_i32(base, "input_ids", ids_prompt)) return 1;
    std::vector<int32_t> newtok(gen.begin() + (long)ids_prompt.size(), gen.end());
    std::string txt = tok.decode(newtok);
    // strip leading/trailing whitespace
    auto a = txt.find_first_not_of(" \t\n"); auto b = txt.find_last_not_of(" \t\n");
    txt = (a==std::string::npos) ? "" : txt.substr(a, b-a+1);
    std::string ref; if (!mttest::load_kv_str(base, "baseline.text", ref)) return 1;
    if (txt != ref) { std::fprintf(stderr,"decode mismatch:\n got: %s\n ref: %s\n", txt.c_str(), ref.c_str()); return 1; }
    std::printf("ok tokenizer: eos/audio ids + roundtrip + decode==baseline.text\n");
    return 0;
}

// Ports moss_transcribe_diarize/tests/test_subtitle_export.py 1:1.
#include "subtitle.hpp"

#include <cstdio>
#include <map>
#include <string>
#include <vector>

using mt::SubtitleSegment;
using mt::SubtitleStyle;

static int g_fail = 0;

static void expect(bool cond, const char* name) {
    if (!cond) { ++g_fail; std::fprintf(stderr, "FAIL %s\n", name); }
    else std::printf("ok %s\n", name);
}

static bool has(const std::string& hay, const std::string& needle) {
    return hay.find(needle) != std::string::npos;
}

int main() {
    // test_time_formatters
    expect(mt::format_srt_time(3661.234) == "01:01:01,234" &&
           mt::format_ass_time(3661.23) == "1:01:01.23", "time_formatters");

    // test_export_srt
    {
        std::string t = mt::to_srt({{"seg_0001", 0.5, 2.0, "S01", "hello"}});
        expect(has(t, "00:00:00,500 --> 00:00:02,000") && has(t, "S01: hello"),
               "export_srt");
    }

    // test_export_srt_with_speaker_names
    {
        std::map<std::string, std::string> names = {{"S01", "Alice"}};
        std::string t = mt::to_srt({{"seg_0001", 0.5, 2.0, "S01", "hello"}},
                                   /*show_speaker=*/true, names);
        expect(has(t, "Alice: hello"), "export_srt_with_speaker_names");
    }

    // test_export_ass
    {
        SubtitleStyle style;
        style.font_size = 42;
        style.show_speaker = false;
        std::string t = mt::to_ass({{"seg_0001", 0.5, 2.0, "S01", "hello"}},
                                   style, /*video_width=*/1280, /*video_height=*/720);
        expect(has(t, "PlayResX: 1280") &&
               has(t, "Style: Speaker_S01,Noto Sans CJK SC,42") &&
               has(t, "Dialogue: 0,0:00:00.50,0:00:02.00,Speaker_S01") &&
               has(t, "hello"),
               "export_ass");
    }

    // test_export_ass_with_speaker_names
    {
        SubtitleStyle style;
        style.font_size = 42;
        style.speaker_names = {{"S01", "Alice"}};
        std::string t = mt::to_ass({{"seg_0001", 0.5, 2.0, "S01", "hello"}},
                                   style, 1280, 720);
        expect(has(t, "Alice: hello"), "export_ass_with_speaker_names");
    }

    // test_export_json
    {
        std::string t = mt::to_json({{"seg_0001", 0, 1, "S01", "hello"}});
        expect(has(t, "\"id\": \"seg_0001\"") && has(t, "\"text\": \"hello\""),
               "export_json");
    }

    // Integer-valued timestamps >= 10 must render like Python json.dumps
    // (60.0 / 132.0, never 6e+01) -- regression lock for fmt_json_number.
    {
        std::string t = mt::to_json({{"seg_0001", 60, 132, "S01", "x"}});
        expect(has(t, "\"start\": 60.0") && has(t, "\"end\": 132.0") &&
                   !has(t, "e+0") && !has(t, "E+0"),
               "export_json_integer_timestamps");
    }

    if (g_fail) { std::fprintf(stderr, "%d test(s) failed\n", g_fail); return 1; }
    std::printf("all subtitle_export tests passed\n");
    return 0;
}

// Phase 1 end-to-end front-end parity: chain audio_io -> mel -> whisper_encoder
// -> audio_adaptor from a raw wav and confirm it reproduces the dumped
// `audio_embeds`. This composes the already-passing Phase 1 components plus the
// per-chunk encoder trim that the C++ get_audio_features equivalent performs.
//
// ggml ne=[D,T] (D contiguous) has the same byte order as torch [T,D] row-major
// (D contiguous), so the flat buffers compare directly.
#include "audio_io.hpp"
#include "mel.hpp"
#include "whisper_encoder.hpp"
#include "audio_adaptor.hpp"
#include "parity.hpp"
#include <cstdlib>
#include <cstdio>
#include <vector>
#include <cstdint>

int main() {
    const char* gguf = std::getenv("MTD_TEST_GGUF");
    const char* base = std::getenv("MTD_TEST_BASELINE");
    if (!gguf || !base) return 77;

    mt::ModelLoader m;
    if (!m.load(gguf)) { std::fprintf(stderr, "load gguf failed\n"); return 1; }
    m.promote_small_f16_to_f32();
    const mt::Config& c = m.config();

    // 1. Load raw audio (jfk short.wav ~11 s -> ~176000 samples at 16 kHz).
    mt::Audio a;
    if (!mt::load_audio_16k_mono("tests/fixtures/short.wav", a)) {
        std::fprintf(stderr, "load_audio failed\n"); return 1;
    }
    const size_t n_unpadded = a.samples.size();

    // 2. Compute the true token length from the UNPADDED sample count -- this is
    //    the reference get_audio_features logic, not a baseline lookup.
    //    stride = feat_hop * WHISPER_ENCODER_STRIDE(2) * audio_merge_size.
    const int WHISPER_ENCODER_STRIDE = 2;
    const int stride = c.feat_hop * WHISPER_ENCODER_STRIDE * c.audio_merge_size; // 160*2*4=1280
    const int token_len = (int)((n_unpadded - 1) / (size_t)stride) + 1;          // 138 for jfk
    std::fprintf(stderr, "e2e: n_unpadded=%zu stride=%d token_len=%d\n",
                 n_unpadded, stride, token_len);
    if (token_len != 138) {
        std::fprintf(stderr, "token_len=%d != expected 138\n", token_len);
        return 1;
    }

    // 3. Pad/trim to a single 30 s chunk (feat_n_samples = 480000).
    a.samples.resize(c.feat_n_samples, 0.0f);

    // 4. mel -> [80, 3000].
    mt::WhisperMel mel(m);
    std::vector<float> feat; int n_mels = 0, T = 0;
    mel.compute(a.samples, feat, n_mels, T);

    // 5. encoder -> [1024, 1500] (feature-fastest eh[t*1024 + d]).
    mt::WhisperEncoder enc(m);
    std::vector<float> eh; int eT = 0, eD = 0;
    enc.encode(feat, n_mels, T, eh, eT, eD);

    // 6. Trim the padded encoder output to token_len*4 frames before the adaptor.
    //    Feature-fastest layout: the first token_len*4 frames are the first
    //    token_len*4*eD floats.
    const int Ttrim = token_len * 4; // 552
    if (Ttrim > eT) { std::fprintf(stderr, "trim %d > eT=%d\n", Ttrim, eT); return 1; }
    eh.resize((size_t)Ttrim * (size_t)eD);
    eT = Ttrim;

    // 7. adaptor -> N = token_len = 138.
    mt::AudioAdaptor ad(m);
    std::vector<float> emb; int N = 0, H = 0;
    ad.apply(eh, eT, eD, emb, N, H);
    std::fprintf(stderr, "e2e: N=%d H=%d\n", N, H);
    if (N != 138) { std::fprintf(stderr, "N=%d != expected 138\n", N); return 1; }

    // 8. Compare to the dumped audio_embeds (138x1024). Looser tolerance to
    //    absorb accumulation across mel + encoder + adaptor; cos still >= 0.99999.
    std::vector<float> ref; std::vector<int64_t> rsh;
    if (!mttest::load_baseline(base, "audio_embeds", ref, rsh)) return 1;
    bool ok = mttest::compare(emb, ref, "audio_path_e2e", /*atol*/5e-2f, /*rtol*/5e-2f);
    return ok ? 0 : 1;
}
